mutations.find:
const before = this.listQueue();
const ticket = before.find((t) => t.playerId === playerId);
if (!ticket) return null;
this.dequeue(playerId);
return ticket;

mutations.replace:
const ticket = this.listQueue().find((t) => t.playerId === playerId)
  || { playerId, playerName: playerId, level: 3, timestamp: Date.now() };
this.dequeue(playerId);
return ticket;
